{"version":3,"file":"RequestList.jsdbx","sources":["../../src/client/components/RequestList.tsx"],"sourcesContent":["import React, { useState, useEffect } from "react";
import { fetchRequests } from "../services/api";

interface Props {
  navigateToView: (v: string, id?: string | null, o?: { title?: string }) => void;
}

const d = (f: any) => f?.display_value || f || "";
const v = (f: any) => f?.value || f || "";

const STATE_CLASSES: Record<string, string> = {
  requested: "badge--info", pending_ehs_approval: "badge--warning", approved: "badge--positive",
  in_progress: "badge--info", completed: "badge--positive", cancelled: "badge--muted", rejected: "badge--critical",
};

export default function RequestList({ navigateToView }: Props) {
  const [records, setRecords] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    fetchRequests().then(setRecords).catch(e => setError(e.message)).finally(() => setLoading(false));
  }, []);

  return (
    <div className="request-list">
      <div className="request-list__header">
        <h2 className="request-list__title">My Access Requests</h2>
        <a href="?view=create" className="nav-btn nav-btn--primary" onClick={e => { e.preventDefault(); navigateToView("create", null, { title: "New Access Request" }); }}>+ New Request</a>
      </div>
      {loading && <div className="portal-loading"><div className="portal-loading__spinner" /><p className="portal-loading__text">Loading requests...</p></div>}
      {error && <div className="form-error">{error}</div>}
      {!loading && !error && records.length === 0 && (
        <div className="empty-state">
          <p>No access requests found.</p>
          <a href="?view=create" className="nav-btn nav-btn--primary" onClick={e => { e.preventDefault(); navigateToView("create"); }}>Submit Your First Request</a>
        </div>
      )}
      {!loading && records.length > 0 && (
        <div className="request-list__table">
          <div className="list-header">
            <span>Number</span><span>State</span><span>Visit Type</span><span>Start</span><span>Host</span>
          </div>
          {records.map((r: any) => (
            <div key={v(r.sys_id)} className="list-row" onClick={() => navigateToView("detail", v(r.sys_id), { title: `Request ${d(r.number)}` })}>
              <span className="list-row__number">{d(r.number)}</span>
              <span><span className={`badge ${STATE_CLASSES[v(r.state)] || ""}`}>{d(r.state)}</span></span>
              <span>{d(r.visit_type)}</span>
              <span>{d(r.scheduled_start)}</span>
              <span>{d(r.host_employee)}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
"],"names":["d","f","display_value","v","value","STATE_CLASSES","requested","pending_ehs_approval","approved","in_progress","completed","cancelled","rejected","RequestList","navigateToView","records","setRecords","useState","loading","setLoading","error","setError","useEffect","fetchRequests","then","catch","e","message","finally","_jsxs","div","className","_jsx","h2","children","a","href","onClick","preventDefault","title","p","length","span","map","r","sys_id","number","state","visit_type","scheduled_start","host_employee"],"mappings":"uJAOA,CAAA,CAAA,CAAA,CAAMA,CAAI,CAACC,GAAWA,CAAGC,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAiBD,CAAK,CAAA,CAAA,CAAA,CAAA,CACzCE,CAAI,CAACF,GAAWA,CAAGG,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAASH,CAAK,CAAA,CAAA,CAAA,CAAA,CAEjCI,CAAwC,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAC5CC,UAAW,CAAeC,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAsB,iBAAkBC,CAAU,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAC5EC,YAAa,CAAeC,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAW,CAAmBC,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAW,CAAgBC,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAAA,CAAU,iBACjG,CAEe,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAASC,CAAY,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAEC,CAAc,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAA,CAAS,EAC3D,CAAM,CAAA,CAAA,CAACC,CAASC,CAAAA,CAAAA,CAAAA,CAAAA,CAA